React depends heavily on immutable data to detect changes.

const Sum: React.FC = () => {
  const [a, setA] = useState(20);
  const [b, setB] = useState(20);

  const handleAChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = Number(e.target.value);
    setA(value);
  };

  const handleBChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = Number(e.target.value);
    setB(value);
  };

  return (
    <>
      <div>
        <input onChange={handleAChange} />
        <input onChange={handleBChange} />
      </div>
      <div>{a} + {b} = {a + b}</div>
    </>

  )
};



In this example, we only have two pieces of state, and it is still manageable.
But when the state in your component starts to grow, it becomes difficult to manage. You begin losing track…
